Use through workflow.

             //Called from within a workflow class.
             string EnvironmentSetting =
               UserSession.UserConfig.AppSettings["SomeSetting"].ToString();


             //Called from another application needing Environment information

             //DataAccess created earlier
             RFS_Environment Env = new RFS_Environment(DataAccess, "");
             Env.EnvironmentID = "SomeEnvId";

             if (Env.Fetch())
             {
               //Create config
               Configuration Config =
                     new Configuration(Env.Settings, Env.EnvironmentID);

               string EnvironmentSetting = Config.AppSettings["SomeSetting"].ToString();
             }

